// ==UserScript==
// @name         Shopee Đặt Đơn Tự Động (Bản Tinh Gọn Cốt Lõi)
// @namespace    https://shopee.vn/
// @version      5.1
// @description  Chỉ giữ lại duy nhất công cụ Đặt đơn tự động của Shopee từ mã nguồn mới (Loại bỏ game, live, flashsale, devtools)
// @author       DZUx
// @match        https://shopee.vn/*
// @grant        none
// @run-at       document-idle
// ==/UserScript==

/**
 * BỘ LẮNG NGHE CHECKOUT THỤ ĐỘNG & TỐI ƯU SIÊU TỐC (ZERO-LATENCY PASSIVE HOOK)
 * - Trả Promise trực tiếp, không async/await microtask overhead.
 * - Tự động bắt gói tin /api/v4/checkout/get nạp danh sách thẻ & số dư vào Dropdown.
 * - Tự động lưu cache __LAST_CHECKOUT_GET_DATA__ để nạp thẻ ngay lập tức khi mở trang.
 */
(function() {
  if (typeof window === 'undefined') return;
  if (window.__PASSIVE_CHECKOUT_TAP__) return;
  window.__PASSIVE_CHECKOUT_TAP__ = true;
  const _origFetch = window.fetch;
  if (!_origFetch) return;

  window.fetch = function(...args) {
    const p = _origFetch.apply(this, args);
    p.then(function(res) {
      try {
        const url = typeof args[0] === 'string' ? args[0] : (args[0] && args[0].url ? args[0].url : '');
        if (url && url.indexOf('/api/v4/checkout/get') !== -1 && res && res.ok) {
          res.clone().json().then(function(data) {
            if (data && (!data.error || Number(data.error) === 0)) {
              try {
                localStorage.setItem('__LAST_CHECKOUT_GET_DATA__', JSON.stringify(data));
              } catch (_) {}
              if (typeof window.refreshPaymentOptionsFromCheckout === 'function') {
                console.log('[Shopee AutoBuy] ⚡ Tự động cập nhật danh sách thẻ & phương thức từ Checkout:', data);
                setTimeout(function() {
                  try {
                    window.refreshPaymentOptionsFromCheckout(data);
                  } catch (e) {
                    console.warn('[Shopee AutoBuy] Lỗi cập nhật phương thức thanh toán:', e);
                  }
                }, 50);
              }
            }
          }).catch(function() {});
        }
      } catch (_) {}
    }).catch(function() {});
    return p;
  };
})();

// Vô hiệu hóa bẫy devtool nếu có
if (typeof window !== 'undefined') {
  window.DisableDevtool = function() {
    return { isRunning: false, stop: function(){}, isDevToolOpened: function(){ return false; } };
  };
}

