  // Tự động khởi chạy Đặt đơn tự động ở chế độ đầy đủ khi tải trang
  function launchAutoOrder() {
    if (typeof window.shopeeAutoOrder === 'function') {
      window.shopeeAutoOrder('full');
    }
    // Nút nổi mở lại giao diện Đặt Đơn Tự Động
    setTimeout(function() {
      if (!document.getElementById('btn-open-shopee-autobuy')) {
        var btn = document.createElement('div');
        btn.id = 'btn-open-shopee-autobuy';
        btn.innerHTML = '⚡ Đặt Đơn Tự Động';
        btn.style.cssText = 'position:fixed;bottom:24px;right:24px;z-index:999999;background:linear-gradient(135deg,#ee4d2d,#ff6b35);color:#fff;padding:10px 18px;border-radius:24px;font-weight:bold;font-size:13px;box-shadow:0 4px 16px rgba(238,77,45,0.45);cursor:pointer;user-select:none;font-family:sans-serif;transition:transform 0.2s ease;';
        btn.onmouseover = function() { btn.style.transform = 'scale(1.06)'; };
        btn.onmouseout = function() { btn.style.transform = 'scale(1)'; };
        btn.onclick = function() {
          if (typeof window.shopeeAutoBuyUI === 'function') {
            window.shopeeAutoBuyUI();
          } else if (typeof window.shopeeAutoOrder === 'function') {
            window.shopeeAutoOrder('full');
          }
        };
        if (document.body) document.body.appendChild(btn);
      }
    }, 1000);
  }

  if (document.readyState === 'loading') {
    window.addEventListener('DOMContentLoaded', launchAutoOrder);
  } else {
    launchAutoOrder();
  }

